package br.com.xopy;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ServiceExecutionTest {
 JdbcTemplate db;Identity identity;ServiceContractController contracts;ChatController chat;ServiceExecutionController api;Jwt jwt;UUID uid,id,cid,other;Map<String,Object> contract;
 @BeforeEach void setup(){db=mock(JdbcTemplate.class);identity=mock(Identity.class);contracts=mock(ServiceContractController.class);chat=mock(ChatController.class);api=new ServiceExecutionController(db,identity,contracts,chat);uid=UUID.randomUUID();id=UUID.randomUUID();cid=UUID.randomUUID();other=UUID.randomUUID();jwt=Jwt.withTokenValue("test").header("alg","HS256").subject(uid.toString()).build();when(identity.id(jwt)).thenReturn(uid);contract=new HashMap<>(Map.of("id",id,"conversation_id",cid,"customer_id",other,"provider_user_id",uid,"accepted_at",new Date(),"status","paid","execution_status","scheduled"));when(contracts.authorized(id,uid,true)).thenReturn(contract);when(contracts.authorized(id,uid,false)).thenReturn(contract);}
 void customer(){contract.put("customer_id",uid);contract.put("provider_user_id",other);}
 ServiceExecutionController.Update update(String action,String note){return new ServiceExecutionController.Update(action,note,true);}
 void noWrites(){verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void providerStartsPaidService()throws Exception{assertEquals("in_progress",api.update(jwt,id,update("start","Início agendado")).get("execution_status"));verify(db).update(contains("started_at=now()"),eq(id));verify(db).update(contains("INSERT INTO service_execution_events"),eq(id),eq(uid),eq("start"),eq("Início agendado"));verify(chat).send(eq(jwt),eq(cid),any());}
 @Test void customerCannotStartOrReportProgress(){customer();for(String action:List.of("start","progress","complete"))assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update(action,"Texto")));noWrites();}
 @Test void providerCannotConfirmOrRequestAdjustments(){contract.put("execution_status","awaiting_confirmation");for(String action:List.of("confirm_delivery","request_adjustments"))assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update(action,"Ajustar")));noWrites();}
 @Test void executionRequiresApprovedPayment(){for(String status:List.of("awaiting_payment","payment_pending","payment_rejected","refunded","charged_back","payment_review")){contract.put("status",status);assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("start","")));}noWrites();}
 @Test void executionRequiresConfirmedContract(){contract.remove("accepted_at");assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("start","")));noWrites();}
 @Test void cannotSkipExecution(){assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("complete","")));customer();assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("confirm_delivery","")));noWrites();}
 @Test void progressRequiresDescriptionAndRunningService(){contract.put("execution_status","in_progress");assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("progress","   ")));contract.put("execution_status","scheduled");assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("progress","Materiais recebidos")));noWrites();}
 @Test void runningServiceAcceptsProgress()throws Exception{contract.put("execution_status","in_progress");assertEquals("in_progress",api.update(jwt,id,update("progress","Instalação em andamento")).get("execution_status"));verify(db).update(contains("INSERT INTO service_execution_events"),eq(id),eq(uid),eq("progress"),eq("Instalação em andamento"));}
 @Test void completionWaitsForCustomer()throws Exception{contract.put("execution_status","in_progress");assertEquals("awaiting_confirmation",api.update(jwt,id,update("complete","Concluído conforme escopo")).get("execution_status"));verify(db).update(contains("reported_completed_at=now()"),eq(id));verify(db,never()).update(contains("delivery_confirmed_at=now()"),any(Object[].class));}
 @Test void customerMustExplicitlyConfirmReceipt(){customer();contract.put("execution_status","awaiting_confirmation");assertThrows(ResponseStatusException.class,()->api.update(jwt,id,new ServiceExecutionController.Update("confirm_delivery","",false)));noWrites();}
 @Test void customerConfirmsDelivery()throws Exception{customer();contract.put("execution_status","awaiting_confirmation");assertEquals("completed",api.update(jwt,id,update("confirm_delivery","Recebido")).get("execution_status"));verify(db).update(contains("delivery_confirmed_at=now()"),eq(id));}
 @Test void adjustmentRequiresReason(){customer();contract.put("execution_status","awaiting_confirmation");assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("request_adjustments"," ")));noWrites();}
 @Test void requestedAdjustmentsReopenExecution()throws Exception{customer();contract.put("execution_status","awaiting_confirmation");assertEquals("in_progress",api.update(jwt,id,update("request_adjustments","Revisar acabamento")).get("execution_status"));verify(db).update(contains("INSERT INTO service_execution_events"),eq(id),eq(uid),eq("request_adjustments"),eq("Revisar acabamento"));}
 @Test void cannotModifyCompletedService(){contract.put("execution_status","completed");for(String action:List.of("start","progress","complete"))assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update(action,"Texto")));customer();for(String action:List.of("confirm_delivery","request_adjustments"))assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update(action,"Texto")));noWrites();}
 @Test void outsiderCannotReadOrUpdate(){when(contracts.authorized(id,uid,false)).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));when(contracts.authorized(id,uid,true)).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.get(jwt,id));assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("start","")));assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(5,"")));verifyNoInteractions(db);}
 @Test void providerCannotReviewOwnService(){contract.put("execution_status","completed");contract.put("delivery_confirmed_at",new Date());assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(5,"")));noWrites();}
 @Test void reviewRequiresDeliveryConfirmation(){customer();for(String state:List.of("scheduled","in_progress","awaiting_confirmation","completed")){contract.put("execution_status",state);assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(5,"")));}noWrites();}
 @Test void rejectInvalidRatingsAndOversizeComment(){customer();contract.put("execution_status","completed");contract.put("delivery_confirmed_at",new Date());for(Integer rating:Arrays.asList(null,0,-1,6))assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(rating,"")));assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(5,"x".repeat(5001))));noWrites();}
 @Test void oneReviewPerContract(){customer();contract.put("execution_status","completed");contract.put("delivery_confirmed_at",new Date());when(db.queryForList(contains("SELECT id FROM professional_reviews"),eq(id))).thenReturn(List.of(Map.of("id",UUID.randomUUID())));assertThrows(ResponseStatusException.class,()->api.review(jwt,id,new ServiceExecutionController.Review(5,"")));noWrites();}
 @Test void completedCustomerReviewUsesContractParticipants()throws Exception{customer();contract.put("execution_status","completed");contract.put("delivery_confirmed_at",new Date());var result=api.review(jwt,id,new ServiceExecutionController.Review(4,"Bom serviço"));assertEquals(4,result.get("rating"));verify(db).update(contains("INSERT INTO professional_reviews"),any(),eq(id),eq(other),eq(uid),eq(4),eq("Bom serviço"));verify(chat).send(eq(jwt),eq(cid),argThat(text->text.content().contains("Bom serviço")));}
 @Test void laterRefundDoesNotEraseEligibilityToReviewCompletedWork()throws Exception{customer();contract.put("execution_status","completed");contract.put("delivery_confirmed_at",new Date());contract.put("status","refunded");assertEquals(3,api.review(jwt,id,new ServiceExecutionController.Review(3,"Serviço realizado, houve reembolso")).get("rating"));}
 @Test void listIsScopedToBothParticipantRoles(){api.list(jwt);verify(db).queryForList(contains("WHERE c.customer_id=? OR c.provider_user_id=?"),eq(uid),eq(uid));}
 @Test void unknownActionAndLongNotesRejected(){assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("paid","")));assertThrows(ResponseStatusException.class,()->api.update(jwt,id,update("start","x".repeat(2001))));noWrites();}
}
